/**
 * The CLI reference (08 §6 `cc:gen`, 07 §4): one Markdown page generated from the command
 * catalogue, so the reference and each command's `--help` cannot drift apart.
 */
import { DESCRIPTION } from './help.js';
import { COMMANDS, DEFAULT_LIMIT, flagsOf, GLOBAL_FLAGS, usageOf } from './spec.js';

function cell(text: string): string {
  return text.replaceAll('|', '\\|');
}

export function renderReference(): string {
  const lines = [
    '# `cc-axi` command reference',
    '',
    'Generated by `pnpm cc:gen` from `apps/cli/src/spec.ts`. Do not edit by hand. The design is',
    '[07 §4](../../../docs/design/07-agent-friendly-design.md#4-cc-axi-the-axi-command-line).',
    '',
    `${DESCRIPTION}.`,
    '',
    '`cc-axi` with no arguments prints the home view. `-v`, `-V` and `--version` print the bare',
    `version. Flags come after the command. Lists show ${DEFAULT_LIMIT} rows unless \`--limit\``,
    'says otherwise. Output is TOON on stdout, errors included; exit codes are 0 (success or',
    '`no-op`), 1 (an error) and 2 (a usage error: `E_USAGE`, `E_UNKNOWN_FLAG`).',
    '',
    'Global flags, accepted by every command:',
    '',
    ...GLOBAL_FLAGS.map(
      (flag) =>
        `- \`${flag.name} ${flag.value ?? ''}\`: ${flag.description}${flag.default === undefined ? '' : ` (default: ${flag.default})`}`,
    ),
    "- `--help`: the command's flags, defaults and examples",
    '',
    "The local API is found through `<userData>`, read from `$CC_PROFILE_DIR`, or the app's default user data",
    'directory; `$CC_PRINCIPAL` names the principal when `--principal` is not given.',
  ];
  for (const command of COMMANDS) {
    lines.push(
      '',
      `## \`cc-axi ${command.path}\``,
      '',
      `${command.summary}.`,
      '',
      '```text',
      usageOf(command),
      '```',
      '',
    );
    if (command.args.length > 0) {
      lines.push('| Argument | Meaning |', '| --- | --- |');
      for (const arg of command.args)
        lines.push(`| \`${cell(arg.placeholder)}\` | ${cell(arg.description)} |`);
      lines.push('');
    }
    const flags = flagsOf(command).filter((flag) => !GLOBAL_FLAGS.includes(flag));
    if (flags.length > 0) {
      lines.push('| Flag | Meaning | Default |', '| --- | --- | --- |');
      for (const flag of flags) {
        const name = flag.value === undefined ? flag.name : `${flag.name} ${flag.value}`;
        const notes = `${flag.required === true ? ' Required.' : ''}${flag.repeat === true ? ' Repeatable.' : ''}`;
        lines.push(
          `| \`${cell(name)}\` | ${cell(flag.description)}.${notes} | ${cell(flag.default ?? '')} |`,
        );
      }
      lines.push('');
    }
    lines.push(
      `Local API: ${command.methods.length === 0 ? 'none' : command.methods.map((method) => `\`${method}\``).join(', ')}.`,
      '',
      'Examples:',
      '',
      '```text',
      ...command.examples,
      '```',
    );
  }
  return `${lines.join('\n')}\n`;
}
